<script>import {register} from '../api/authApi.js';import {authStore} from '../states/authStore.js';import {router} from '../../../router.js';let name=$state('');let email=$state('');let password=$state('');let error=$state('');let busy=$state(false);async function submit(e){e.preventDefault();if(password.length<8){error='Kata sandi minimal 8 karakter.';return;}error='';busy=true;try{const data=await register(name.trim(),email.trim(),password);const token=data.token||data.access_token||data.accessToken;if(token){authStore.setSession(token,data.user||null);router.navigate('/');}else{router.navigate('/auth/login');}}catch(err){error=err.message||'Pendaftaran gagal.';}finally{busy=false;}}</script>
<svelte:head><title>Daftar · Delcom Link Tree</title><meta name="description" content="Buat akun Delcom Link Tree."/></svelte:head><div class="auth-icon">↗</div><p class="eyebrow">MULAI SEKARANG</p><h1>Buat akun baru</h1><p class="muted">Susun tautanmu agar lebih mudah dibagikan.</p><form class="form-stack auth-form" onsubmit={submit}><label for="register-name">Nama</label><input id="register-name" bind:value={name} required autocomplete="name"/><label for="register-email">Email</label><input id="register-email" type="email" bind:value={email} required autocomplete="email"/><label for="register-password">Kata sandi</label><input id="register-password" type="password" bind:value={password} required minlength="8" autocomplete="new-password"/><p class="muted small">Gunakan minimal 8 karakter.</p>{#if error}<p class="error" role="alert">{error}</p>{/if}<button class="btn btn-primary btn-full" disabled={busy}>{busy?'Mendaftarkan…':'Buat akun'}</button></form><p class="auth-switch">Sudah punya akun? <a href="/auth/login" onclick={(e)=>{e.preventDefault();router.navigate('/auth/login')}}>Masuk</a></p>
